def solve(n, k, arr):

	def moves_needed(m):
		offset = 0
		for i in range(m, -1, -1):
			num = (arr[i] + offset) % 10
			if num != 0:
				offset += 10 - num
		return offset
	l = 0
	r = n - 1
	while l < r:
		m = (l + r) // 2
		if moves_needed(m) > k:
			r = m
		else:
			l = m + 1
	if l == n - 1 and moves_needed(n - 1) <= k:
		return n
	return l
for _ in range(int(input())):
	(n, k) = list(map(int, input().split()))
	arr = list(map(int, input()))
	print(solve(n, k, arr))
